mapper.select:
select count(*)
from chat_room_user
where room_id = #{room_id}
and user_id = #{user_id}

mapper.update:
update chat_message
set read_count = 0
where room_id = #{room_id}
and sender_id != #{user_id}
and read_count = 1

mapper.select:
SELECT user_id
FROM chat_room_user
WHERE room_id = #{roomId}
AND user_id != #{userId}

SELECT r.room_id AS roomId, r.room_name AS roomName, lm.content AS lastMessage, lm.created_at AS lastTime, NVL(uc.unread_count, 0) AS unreadCount FROM chat_room r JOIN chat_room_user ru ON r.room_id = ru.room_id AND ru.user_id = #{userId}
LEFT JOIN ( SELECT room_id, content, created_at FROM ( SELECT room_id, content, created_at, ROW_NUMBER() OVER ( PARTITION BY room_id ORDER BY message_id DESC ) rn FROM chat_message ) WHERE rn = 1 ) lm ON lm.room_id = r.room_id
LEFT JOIN ( SELECT room_id, COUNT(*) AS unread_count FROM chat_message WHERE sender_id != #{userId} AND read_count = 1 GROUP BY room_id ) uc ON uc.room_id = r.room_id
WHERE r.room_id = #{roomId}
